// Frozen before opening the new157 reference values. No center-point accuracy metric.
export const finitePoint = p => !!p && Number.isFinite(p.x) && Number.isFinite(p.y);
export const inFrame = p => finitePoint(p) && p.x >= 0 && p.x <= 1 && p.y >= 0 && p.y <= 1;
// Same validated transform as native48v2: model plane is unmirrored; saved PNG is mirrored.
// Annotation coordinates are used directly and are never flipped a second time.
export const toOriginalNative = p => finitePoint(p) ? { x: (1 - p.x) * 639, y: p.y * 479 } : null;
export const visibleIndex = r => r.tipVisibility === 'VISIBLE' && r.anatomicalDigit === 'INDEX';
export const visibleIndexPointing = r => visibleIndex(r) && r.pointingIntent === 'POINT';
export const countValues = (rows, key) => rows.reduce((out, r) => (out[r[key]] = (out[r[key]] ?? 0) + 1, out), {});
export function distribution(values) {
  const a = values.filter(Number.isFinite).sort((x, y) => x - y);
  const q = p => a[Math.max(0, Math.ceil(a.length * p) - 1)] ?? null;
  return { n: a.length, median: q(.5), p95: q(.95), maximum: a.at(-1) ?? null };
}
export function validRectangle(r) {
  return Array.isArray(r) && r.length === 4 && r.every(Number.isInteger) &&
    0 <= r[0] && r[0] < r[2] && r[2] <= 639 && 0 <= r[1] && r[1] < r[3] && r[3] <= 479;
}
export function scorePoint(normalized, rectangle) {
  const finite = finitePoint(normalized), available = inFrame(normalized);
  const p = available ? toOriginalNative(normalized) : null;
  const d = p && rectangle ? Math.hypot(Math.max(rectangle[0] - p.x, 0, p.x - rectangle[2]),
    Math.max(rectangle[1] - p.y, 0, p.y - rectangle[3])) : null;
  return { finite, available, nativePoint: p, boxAssessed: d !== null,
    insideBox: d === null ? null : d === 0, outsideBoxDistanceLowerBoundPixels: d };
}
export function boxSummary(items, kind) {
  const available = items.filter(r => r[kind].available), boxed = items.filter(r => r.uncertaintyRectangle !== null);
  const assessed = available.filter(r => r[kind].boxAssessed);
  return { referenceFrames: items.length, referenceFramesWithBox: boxed.length,
    availablePositions: available.length, missingPositions: items.length - available.length,
    availableWithBox: assessed.length, availableWithoutBox: available.length - assessed.length,
    insideBox: assessed.filter(r => r[kind].insideBox).length,
    outsideBox: assessed.filter(r => r[kind].insideBox === false).length,
    outsideBoxDistanceLowerBoundPixels: distribution(assessed.map(r => r[kind].outsideBoxDistanceLowerBoundPixels)),
    positiveOutsideDistanceLowerBoundPixels: distribution(assessed.filter(r => !r[kind].insideBox).map(r => r[kind].outsideBoxDistanceLowerBoundPixels)) };
}
export function summarize(items) {
  const v = items.filter(visibleIndex), p = items.filter(visibleIndexPointing);
  const unresolvedBox = items.filter(r => !visibleIndex(r) && r.uncertaintyRectangle !== null);
  return { referenceFrames: items.length,
    labels: Object.fromEntries(['tipVisibility','anatomicalDigit','pointingIntent','localAdjacentIndexContinuity'].map(k => [k,countValues(items,k)])),
    coarseBoxes: items.filter(r => r.uncertaintyRectangle !== null).length,
    visibleIndexFrames: v.length, visibleIndexPointingFrames: p.length,
    modalities: Object.fromEntries(['raw','measured','ready'].map(kind => [kind, {
      allAvailability: { referenceFrames: items.length, available: items.filter(r=>r[kind].available).length,
        missing: items.filter(r=>!r[kind].available).length },
      visibleIndexBoxAssessment: boxSummary(v,kind),
      visibleIndexPointingBoxAssessment: boxSummary(p,kind),
      unresolvedLabelBoxDiagnosticNotIndexTruth: boxSummary(unresolvedBox,kind),
      explicitContrary: { referenceFrames:items.filter(r=>r.pointingIntent==='CONTRARY').length,
        available:items.filter(r=>r.pointingIntent==='CONTRARY'&&r[kind].available).length },
      explicitNonIndex: { referenceFrames:items.filter(r=>r.anatomicalDigit==='NON_INDEX').length,
        available:items.filter(r=>r.anatomicalDigit==='NON_INDEX'&&r[kind].available).length },
      notVisible: { referenceFrames:items.filter(r=>r.tipVisibility==='NOT_VISIBLE').length,
        available:items.filter(r=>r.tipVisibility==='NOT_VISIBLE'&&r[kind].available).length }
    }])) };
}
export function pairedSummary(gpu, cpu, predicate = () => true) {
  const by = new Map(cpu.map(r=>[r.frameIndex,r]));
  const pairs = gpu.filter(predicate).map(g => ({g,c:by.get(g.frameIndex)}));
  if (pairs.some(p=>!p.c)) throw Error('PAIRED_REFERENCE_MISSING');
  return Object.fromEntries(['raw','measured','ready'].map(kind=>{
    const pairsWithBox = pairs.filter(p=>p.g.uncertaintyRectangle!==null);
    const gains = pairs.filter(p=>!p.g[kind].available&&p.c[kind].available);
    const losses = pairs.filter(p=>p.g[kind].available&&!p.c[kind].available);
    const both = pairsWithBox.filter(p=>p.g[kind].available&&p.c[kind].available);
    const split = (list,arm)=>({insideBox:list.filter(p=>p[arm][kind].insideBox===true).length,
      outsideBox:list.filter(p=>p[arm][kind].insideBox===false).length,
      boxUnknown:list.filter(p=>p[arm][kind].insideBox===null).length});
    return [kind,{referenceFrames:pairs.length,referenceFramesWithBox:pairsWithBox.length,
      availabilityGains:gains.length,availabilityGainsCpuRegion:split(gains,'c'),
      availabilityLosses:losses.length,availabilityLossesGpuRegion:split(losses,'g'),
      bothAvailableWithBox:both.length,
      bothInside:both.filter(p=>p.g[kind].insideBox&&p.c[kind].insideBox).length,
      gpuOutsideCpuInside:both.filter(p=>p.g[kind].insideBox===false&&p.c[kind].insideBox===true).length,
      gpuInsideCpuOutside:both.filter(p=>p.g[kind].insideBox===true&&p.c[kind].insideBox===false).length,
      bothOutside:both.filter(p=>p.g[kind].insideBox===false&&p.c[kind].insideBox===false).length,
      bothMissing:pairs.filter(p=>!p.g[kind].available&&!p.c[kind].available).length}];
  }));
}
export function continuityCoverage(indices, labels) {
  const rows = indices.map(i=>labels.get(i));
  const covered = rows.filter(Boolean).length, complete = covered === indices.length && indices.length > 0;
  const visibleIndexCount = rows.filter(r=>r&&visibleIndex(r)).length;
  const requiredAdjacent = Math.max(0,indices.length-1);
  const supportedAdjacent = rows.slice(1).filter((r,i)=>r&&rows[i]&&indices[i+1]===indices[i]+1&&
    visibleIndex(rows[i])&&visibleIndex(r)&&r.localAdjacentIndexContinuity==='SAME_VISIBLE_INDEX').length;
  return { intervalPackets:indices.length, annotated:covered, missing:indices.length-covered,
    visibleIndex:visibleIndexCount, requiredAdjacent, supportedAdjacent,
    entireIntervalAnnotated:complete,
    completeCoarseVisibleIndexContinuity:complete&&visibleIndexCount===indices.length&&supportedAdjacent===requiredAdjacent };
}
export function logicalEvents(stream, labels) {
  const out=[];let previous=null;
  for(let i=0;i<stream.length;i++){
    const r=stream[i];if(!r.id)continue;
    if(previous&&previous.id!==r.id){
      const beforeFresh=stream.slice(0,i).filter(q=>q.id===previous.id&&q.freshMeasurement).at(-1)??null;
      const afterFresh=stream.slice(i).find(q=>q.id===r.id&&q.freshMeasurement)??null;
      const interval=stream.filter(q=>q.sourceIndex>=previous.sourceIndex&&q.sourceIndex<=r.sourceIndex);
      const coverage=continuityCoverage(interval.map(q=>q.sourceIndex),labels);
      const measurementInterval=beforeFresh&&afterFresh?stream.filter(q=>q.sourceIndex>=beforeFresh.sourceIndex&&q.sourceIndex<=afterFresh.sourceIndex):[];
      out.push({number:out.length+1,beforeIndex:previous.sourceIndex,afterIndex:r.sourceIndex,
        lastFreshIndex:beforeFresh?.sourceIndex??null,firstFreshIndex:afterFresh?.sourceIndex??null,
        scenario:r.scenario,beforeLabel:labels.get(previous.sourceIndex)??null,afterLabel:labels.get(r.sourceIndex)??null,
        coverage,measuredReturnCoverage:continuityCoverage(measurementInterval.map(q=>q.sourceIndex),labels),
        verdict:coverage.completeCoarseVisibleIndexContinuity?'COARSE_VISIBLE_INDEX_INTERVAL_ONLY_NOT_PHYSICAL_IDENTITY_TRUTH':'UNRESOLVED_ANATOMY_OR_ANNOTATION_GAP'});
    }
    previous=r;
  }
  return out;
}
export function summarizeEvents(events) {
  return {logicalReplacements:events.length,
    bothBoundaryEndpointsAnnotated:events.filter(e=>e.beforeLabel&&e.afterLabel).length,
    fullIntervalsAnnotated:events.filter(e=>e.coverage.entireIntervalAnnotated).length,
    completeCoarseVisibleIndexContinuity:events.filter(e=>e.coverage.completeCoarseVisibleIndexContinuity).length,
    unresolved:events.filter(e=>!e.coverage.completeCoarseVisibleIndexContinuity).length,
    fullMeasuredReturnIntervalsAnnotated:events.filter(e=>e.measuredReturnCoverage.entireIntervalAnnotated).length};
}
export function reviewerAgreement(newRows,oldRows){
  const oldBy=new Map(oldRows.map(r=>[r.sourceIndex,r])),pairs=[];
  for(const n of newRows){const o=oldBy.get(n.frameIndex);if(!o)continue;
    if(o.nativeSha256!==n.nativePngSha256)throw Error('OVERLAP_PNG_SHA_MISMATCH');pairs.push({n,o});}
  const comparison={tipVisibility:'tipVisibility',anatomicalDigit:'anatomicalDigit',pointingIntent:'pointingIntent',localAdjacentIndexContinuity:'selectedIndexContinuity'};
  const fields=Object.fromEntries(Object.entries(comparison).map(([nkey,okey])=>{
    const transitions={};let agree=0,oneUnresolved=0,bothUnresolved=0;
    for(const {n,o}of pairs){const a=n[nkey],b=o[okey],key=`${a} / ${b}`;transitions[key]=(transitions[key]??0)+1;
      if(a===b)agree++;if((a==='UNRESOLVED')!==(b==='UNRESOLVED'))oneUnresolved++;
      if(a==='UNRESOLVED'&&b==='UNRESOLVED')bothUnresolved++;}
    return[nkey,{samePngPairs:pairs.length,agree,disagree:pairs.length-agree,oneReviewUnresolved:oneUnresolved,bothUnresolved,transitions}];
  }));
  let bothBoxes=0,overlap=0,disjoint=0,oneBoxOnly=0,neitherBox=0;
  const privatePairs=[];
  for(const {n,o}of pairs){const a=n.uncertaintyRectangle,b=o.endpointRegion?.boundsInclusive;
    let relation='NEITHER_BOX';if(a&&b){bothBoxes++;const intersects=Math.max(a[0],b.left)<=Math.min(a[2],b.right)&&Math.max(a[1],b.top)<=Math.min(a[3],b.bottom);
      relation=intersects?'OVERLAP':'DISJOINT';if(intersects)overlap++;else disjoint++;}
    else if(a||b){oneBoxOnly++;relation='ONE_BOX_ONLY';}else neitherBox++;
    privatePairs.push({frameIndex:n.frameIndex,pngSha256:n.nativePngSha256,newReference:n,oldReference:o,boxRelation:relation});
  }
  return {summary:{samePngPairs:pairs.length,fields,boxes:{bothBoxes,overlap,disjoint,oneBoxOnly,neitherBox},
    continuitySemanticLimitation:'New labels describe immediately adjacent frame continuity. Old selectedIndexContinuity describes continuity from the initially resolved segment, so equality is a value diagnostic, not interchangeable local-adjacency annotation or reliability.'},privatePairs};
}

