import assert from 'node:assert/strict';
import {toOriginalNative,scorePoint,boxSummary,summarize,pairedSummary,continuityCoverage,reviewerAgreement} from './rectangle-metrics.mjs';
const tests=[];const test=(name,fn)=>{fn();tests.push({name,passed:true});};
test('checked single flip and native pixel center scaling',()=>{
 assert.deepEqual(toOriginalNative({x:0,y:0}),{x:639,y:0});assert.deepEqual(toOriginalNative({x:1,y:1}),{x:0,y:479});
 assert.deepEqual(toOriginalNative({x:.25,y:.5}),{x:479.25,y:239.5});
});
test('inclusive rectangle edge and outside distance use no box center',()=>{
 assert.equal(scorePoint({x:1-100/639,y:100/479},[100,100,200,200]).insideBox,true);
 const s=scorePoint({x:1-97/639,y:96/479},[100,100,200,200]);assert.ok(Math.abs(s.outsideBoxDistanceLowerBoundPixels-5)<1e-10);
});
test('off frame and nonfinite are missing rather than clamped',()=>{
 for(const p of[{x:1.1,y:.5},{x:NaN,y:.5},null])assert.equal(scorePoint(p,[0,0,639,479]).available,false);
});
const item=(i,p,overrides={})=>({frameIndex:i,tipVisibility:'VISIBLE',anatomicalDigit:'INDEX',pointingIntent:'POINT',
 localAdjacentIndexContinuity:'UNRESOLVED',uncertaintyRectangle:[100,100,200,200],raw:scorePoint(p,[100,100,200,200]),
 measured:scorePoint(p,[100,100,200,200]),ready:scorePoint(null,[100,100,200,200]),...overrides});
test('missing stays in reference denominator and readiness separate',()=>{
 const a=item(1,{x:1-150/639,y:150/479}),b=item(2,null),s=summarize([a,b]);
 assert.equal(s.modalities.measured.visibleIndexPointingBoxAssessment.referenceFrames,2);
 assert.equal(s.modalities.measured.visibleIndexPointingBoxAssessment.missingPositions,1);
 assert.equal(s.modalities.ready.allAvailability.available,0);
});
test('rectangle alone cannot create visible index or pointing truth',()=>{
 const a=item(1,{x:.5,y:.5},{tipVisibility:'AMBIGUOUS',anatomicalDigit:'UNRESOLVED',pointingIntent:'UNRESOLVED'}),s=summarize([a]);
 assert.equal(s.visibleIndexPointingFrames,0);assert.equal(s.modalities.raw.visibleIndexBoxAssessment.referenceFrames,0);
 assert.equal(s.modalities.raw.unresolvedLabelBoxDiagnosticNotIndexTruth.referenceFrames,1);
 assert.equal(s.modalities.raw.explicitContrary.referenceFrames,0);
});
test('CPU gain outside box distinct from supported inside gain',()=>{
 const g=[item(1,null),item(2,null)],c=[item(1,{x:1-150/639,y:150/479}),item(2,{x:1-250/639,y:250/479})];
 const s=pairedSummary(g,c).measured;assert.equal(s.availabilityGains,2);
 assert.equal(s.availabilityGainsCpuRegion.insideBox,1);assert.equal(s.availabilityGainsCpuRegion.outsideBox,1);
});
test('annotation gap and ambiguous local transition block continuity',()=>{
 const labels=new Map([[1,item(1,null)],[2,item(2,null,{localAdjacentIndexContinuity:'SAME_VISIBLE_INDEX'})]]);
 assert.equal(continuityCoverage([1,2],labels).completeCoarseVisibleIndexContinuity,true);
 assert.equal(continuityCoverage([1,2,3],labels).completeCoarseVisibleIndexContinuity,false);
 labels.set(2,item(2,null,{tipVisibility:'AMBIGUOUS',localAdjacentIndexContinuity:'UNRESOLVED'}));
 assert.equal(continuityCoverage([1,2],labels).completeCoarseVisibleIndexContinuity,false);
});
test('reviewer disagreement and box disjointness remain visible',()=>{
 const n={...item(1,null),nativePngSha256:'a'},o={sourceIndex:1,nativeSha256:'a',tipVisibility:'AMBIGUOUS',anatomicalDigit:'UNRESOLVED',pointingIntent:'UNRESOLVED',selectedIndexContinuity:'UNRESOLVED',endpointRegion:{boundsInclusive:{left:300,top:300,right:400,bottom:400}}};
 const s=reviewerAgreement([n],[o]).summary;assert.equal(s.fields.tipVisibility.disagree,1);assert.equal(s.boxes.disjoint,1);
 assert.throws(()=>reviewerAgreement([n],[{...o,nativeSha256:'b'}]),/SHA_MISMATCH/);
});
console.log(JSON.stringify({classification:'SYNTHETIC_METRIC_CONTRACT_TESTS_NO_REFERENCE_VALUES_READ',tests,passed:tests.length}));
